package com.agenda.clinica.controller;
import com.agenda.clinica.entity.*; import com.agenda.clinica.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class CatalogoController { private final MedicoRepository medicos; private final EspecialidadRepository especialidades; private final PacienteRepository pacientes; public CatalogoController(MedicoRepository m,EspecialidadRepository e,PacienteRepository p){medicos=m;especialidades=e;pacientes=p;} @GetMapping("/public/medicos") public List<Medico> medicos(){return medicos.findByActivoTrue();} @GetMapping("/public/especialidades") public List<Especialidad> especialidades(){return especialidades.findAll();} @GetMapping("/admin/pacientes") public List<Paciente> pacientes(){return pacientes.findAll();} @PostMapping("/admin/medicos") public Medico crearMedico(@RequestBody Map<String,String> b){Especialidad e=especialidades.findById(Long.valueOf(b.get("especialidadId"))).orElseThrow();Medico m=new Medico();m.setNombre(b.get("nombre"));m.setCorreo(b.get("correo"));m.setEspecialidad(e);return medicos.save(m);} @PostMapping("/admin/especialidades") public Especialidad crearEspecialidad(@RequestBody Map<String,String> b){Especialidad e=new Especialidad();e.setNombre(b.get("nombre"));return especialidades.save(e);} }
